mapper.select:
SELECT conversation_id, stock_code, stock_name, title, created_at, updated_at
FROM chat_conversation
WHERE user_id = #{userId}
  AND conversation_id = #{conversationId}

SELECT conversation_id, stock_code, stock_name, title, created_at, updated_at
FROM chat_conversation
WHERE user_id = #{userId}
  AND stock_code = #{stockCode}
ORDER BY updated_at DESC, created_at DESC, conversation_id
LIMIT #{limit}

SELECT conversation_id, role, content, context_content, response_json, created_at
FROM (
	SELECT message_id, conversation_id, role, content, context_content, response_json, created_at
	FROM chat_message
	WHERE conversation_id = #{conversationId}
	ORDER BY message_id DESC
	LIMIT #{limit}
) recent
ORDER BY message_id

mapper.delete:
DELETE FROM chat_conversation
WHERE user_id = #{userId}
  AND conversation_id = #{conversationId}
